        parts = list(map(int, line.split()))
        edges.append((parts[0], parts[1], parts[2]))

    if len(edges) != m:
        pass  # Handle potential incomplete input

    graph = [[] for _ in range(n + 1)]
    for i, (u, v, w) in enumerate(edges, 1):
        graph[u].append((v, w, i))
        graph[v].append((u, w, i))

    def is_connected(u, v):
        visited = [False] * (n + 1)
        queue = deque([u])
        visited[u] = True
        while queue:
            cur = queue.popleft()
            if cur == v:
                return True
            for nxt, _, _ in graph[cur]:
                if not visited[nxt]:
                    visited[nxt] = True
                    queue.append(nxt)
        return False

    # Check 0 edges removed
    if not is_connected(s, t):
        return "0\n0\n"

    INF = float('inf')
    min_cost = INF
    result = None

    # Helper to temporarily remove an edge
    def remove_edge(graph, idx):
        _, u, v, w = edges[idx - 1]
        for i in range(len(graph[u])):
            if graph[u][i][0] == v and graph[u][i][2] == idx:
                graph[u].pop(i)
                return
        for i in range(len(graph[v])):
            if graph[v][i][0] == u and graph[v][i][2] == idx:
                graph[v].pop(i)
                return

    # Helper to restore
    def restore_edge(graph, idx):
        u, v, w = edges[idx - 1]
        entry = (v, w, idx)
        for i, item in enumerate(graph[u]):
            if item[0] == v and item[2] == idx:
                graph[u].pop(i)
                return
        for i, item in enumerate(graph[v]):
            if item[0] == u and item[2] == idx:
                graph[v].pop(i)
                return

    # Try removing 1 edge
    for idx in range(m):
        remove_edge(graph, idx + 1)
        if not is_connected(s, t):
            cost = edges[idx][2]
            if cost < min_cost:
                min_cost = cost
                result = (idx + 1,)
            # no need to restore for single edge optimization
        restore_edge(graph, idx + 1)

    # Try removing 2 edges more efficiently
    if result is None:
        # For each vertex, consider edges incident to it
        for v in range(1, n + 1):
            incident_edges = [(i, e) for i, e in enumerate(edges, 1) if e[0] == v or e[1] == v]
            for i in range(len(incident_edges)):
                for j in range(i + 1, len(incident_edges)):
                    idx1, e1 = incident_edges[i]
                    idx2, e2 = incident_edges[j]
                    if idx1 == idx2:
                        continue
                    remove_edge(graph, idx1)
                    remove_edge(graph, idx2)
                    if not is_connected(s, t):
                        cost = e1[2] + e2[2]
                        if cost < min_cost:
                            min_cost = cost
                            result = (idx1, idx2)
                    restore_edge(graph, idx1)
                    restore_edge(graph, idx2)

    if min_cost == INF:
        return "-1"

    c = len(result)
    if c == 0:
        return "0\n0\n"
    elif c == 1:
        return f"{min_cost}\n1\n{result[0]}\n"
    else:
        return f"{min_cost}\n2\n{result[0]} {result[1]}\n"

