    clauses = []
    for i in range(1, n + 1):
        parts = list(map(int, lines[i].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)

    # For each variable x_i (1-indexed in input, 0-indexed in code):
    # node 2*i represents x_i = True
    # node 2*i + 1 represents x_i = False
    def literal_to_node(liter):
        if liter > 0:
            # Positive literal x|liter|
            return 2 * (liter - 1)
        else:
            # Negative literal -x|-liter|
            var_idx = -liter - 1
            return 2 * var_idx + 1

    def opposite(node):
        return node ^ 1  # toggle between true/false representation

    # Build implication graph
    # Graph has 2*m nodes
    graph = [[] for _ in range(2 * m)]

    for clause in clauses:
        for lit in clause:
            if len(clause) > 1:
                # For clause (l1 ∨ l2 ∨ l3 ∨ ...), we add implications:
                # ¬li → lj for all lj in clause where lj ≠ li
                current = literal_to_node(lit)
                for other in clause:
                    if other != lit:
                        other_node = literal_to_node(other)
                        graph[opposite(current)].append(other_node)

    # Build reverse graph for Kosaraju's algorithm
    rev = [[] for _ in range(2 * m)]
    for u in range(2 * m):
        for v in graph[u]:
            rev[v].append(u)

    # First DFS for order
    visited = [False] * (2 * m)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for i in range(2 * m):
        if not visited[i]:
            dfs1(i)

    # Second DFS to find SCCs
    visited = [False] * (2 * m)
    scc_id = [-1] * (2 * m)
    scc_count = 0

    def dfs2(u, current_scc):
        visited[u] = True
        scc_id[u] = current_scc
        for v in rev[u]:
            if not visited[v]:
                dfs2(v, current_scc)

    for i in range(2 * m - 1, -1, -1):
        if not visited[order[i]]:
            dfs2(order[i], scc_count)
            scc_count += 1

    # Check for unsatisfiability
    # A variable is unsatisfiable if both it and its negation are in the same SCC
    for i in range(m):
        if scc_id[2 * i] == scc_id[2 * i + 1]:
            return "NO"

    # Build assignment: for each variable, pick the literal in the later SCC
    assignment = [0] * m
    for i in range(m):
        if scc_id[2 * i] > scc_id[2 * i + 1]:
            assignment[i] = 1  # x_i = True (use node 2*i which is later)
        else:
            assignment[i] = 0  # x_i = False (use node 2*i+1 which is later)

    return "YES\n" + "".join(map(str, assignment))

