import sys
from collections import defaultdict

sys.setrecursionlimit(300000)

def solution(input_data):
    lines = input_data.strip().split('\n')
    if not lines:
        return "-1"

    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Try to find k cycles first
    cycles = []
    representatives = []
    used = set()

    for start in range(1, n + 1):
        if len(cycles) >= k:
            break
        if start in used:
            continue

        parent = {}
        depth = {}
        parent[start] = None
        depth[start] = 0
        visited = {start}

        stack = [start]
        found = False
        cycle_path = []

        while stack:
            v = stack.pop()

            for neighbor in adj[v]:
                if neighbor == start:
                    # Found cycle back to start
                    cycle_length = depth[v] + 1

                    if cycle_length % 3 != 0 and cycle_length >= 3:
                        # Reconstruct cycle
                        path = []
                        curr = v
                        while curr is not None:
                            path.append(curr)
                            curr = parent[curr]
                        path.append(start)

                        cycles.append(path)
                        representatives.append(start)
                        used.update(path)
                        found = True
                        break
                elif neighbor not in visited:
                    visited.add(neighbor)
                    parent[neighbor] = v
                    depth[neighbor] = depth[v] + 1
                    stack.append(neighbor)

            if found:
                break

    if len(cycles) >= k:
        return output_cycles(k, cycles, representatives)

    # Try to find a long path
    return output_path(n, k, adj)

def output_cycles(k, cycles, representatives):
    res = ["CYCLES"]

    # Find first k cycles with representatives
    selected_cycles = cycles[:k]
    selected_reps = representatives[:k]

