        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # Track earliest time-step to reach each banana count
    # index i represents i bananas, value is time-step or -1 if unreachable
    earliest = [-1] * (m + 1)

    # Set of currently reachable banana counts
    reachable = {0}

    for i in range(n):
        next_reachable = set()
        t, x, y = ops[i]

        for v in reachable:
            # Option 1: Don't apply the operation (0 times)
            next_reachable.add(v)

            # Option 2: Apply the operation a times (1 <= a <= y)
            for a in range(1, y + 1):
                if t == 1:
                    # Type 1: apply k := ceil(k + x) repeatedly a times
                    val = v
                    for _ in range(a):
                        val = math.ceil(val + x)
                    if val <= m:
                        next_reachable.add(val)
                else:
                    # Type 2: apply k := ceil(k * x) repeatedly a times
                    val = v
                    for _ in range(a):
                        val = math.ceil(val * x)
                        if val > m:
                            break
                    if val <= m:
                        next_reachable.add(val)

        # Update earliest time-steps and reachable set
        for v in next_reachable:
            if earliest[v] == -1:
                earliest[v] = i
            else:
                earliest[v] = min(earliest[v], i)

        reachable = next_reachable

    # Build output: for bananas 1 to m, output earliest time-step or -1
    result = [str(earliest[j]) for j in range(1, m + 1)]
    return ' '.join(result) + '\n'

