    """Return plane equation coefficients (a, b, c, d) where a*x + b*y + c*z + d = 0"""
    v1 = vector_sub(p2, p1)
    v2 = vector_sub(p3, p1)
    n = cross(v1, v2)
    mag = math.sqrt(n[0]**2 + n[1]**2 + n[2]**2)
    if mag < 1e-9:
        return None
    n = normalize(n)
    d = -dot(n, p1)
    return (n[0], n[1], n[2], d)

