    n = int(lines[0])
    matrix = []
    for i in range(n):
        row = list(map(int, lines[i + 1].split()))
        matrix.append(row)

    def count_factors(x):
        count2 = 0
        count5 = 0
        while x > 0 and x % 2 == 0:
            count2 += 1
            x //= 2
        while x > 0 and x % 5 == 0:
            count5 += 1
            x //= 5
        return count2, count5

    # dp2[i][j] = max factors of 2 on path to (i,j)
    # dp5[i][j] = max factors of 5 on path to (i,j)
    dp2 = [[0] * n for _ in range(n)]
    dp5 = [[0] * n for _ in range(n)]
    origin2 = [[0] * n for _ in range(n)]
    origin5 = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            c2, c5 = count_factors(matrix[i][j])
            if c2 + dp2[i][j-1] >= c5:  # priority to factors of 2
                dp2[i][j] = c2 + dp2[i][j-1] if j > 0 else c2
                origin2[i][j] = 0 if j > 0 else 1
            elif c5 + dp5[i-1][j] if i > 0 else c5:
                dp5[i][j] = c5 + dp5[i-1][j] if i > 0 else c5
            else:
                pass

            if j > 0 and i > 0:
                choice = 1 if dp2[i-1][j] >= dp2[i][j-1] else 2
                if j > 0:
                    dp2[i][j] = max(dp2[i][j], dp2[i-1][j], dp2[i][j-1])
            else:
                dp2[i][j] = max(dp2[i][j], c2)
            if i > 0 and j > 0:
                dp5[i][j] = max(dp5[i][j], dp5[i-1][j], dp5[i][j-1])
            else:
                dp5[i][j] = max(dp5[i][j], c5)

    final_2 = dp2[n-1][n-1]
    final_5 = dp5[n-1][n-1]
    min_zeros = min(final_2, final_5)

    # Reconstruct path
    path = []
    i, j = n-1, n-1
    while i > 0 or j > 0:
        if i == 0:
            path.append('R')
            j -= 1
        elif j == 0:
            path.append('D')
            i -= 1
        else:
            if dp2[i-1][j] >= dp2[i][j-1]:
                path.append('U')
                i -= 1
            else:
                path.append('L')
                j -= 1
    path.reverse()

    return f"{min_zeros}\n{''.join(path)}"

import sys

sys.setrecursionlimit(300000)

def solution(input_str):
    if not input_str or not input_str.strip():
        return ""

    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    if m == n - 1:
        return ""

    edges_data = []
    for i in range(m):
        parts = list(map(int, lines[i + 1].split()))
        edges_data.append((i, parts[0], parts[1], parts[2]))

    # Union-Find for Kruskal's algorithm
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(i):
        if parent[i] != i:
            parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        pi, pj = find(i), find(j)
        if pi == pj:
            return False
        if rank[pi] < rank[pj]:
            parent[pi] = pj
        elif rank[pi] > rank[pj]:
            parent[pj] = pi
        else:
            parent[pj] = pi
            rank[pi] += 1
        return True

    # Sort edges by weight for MST construction
    sorted_edges = sorted(edges_data, key=lambda x: x[3])

    # Build MST
    mst_adj = [[] for _ in range(n + 1)]
    mst_edge_indices = set()

    for idx, a, b, e in sorted_edges:
        if union(a, b):
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_edge_indices.add(idx)

    # Binary lifting for LCA and max edge queries
    LOG = 20
    up = [[0] * LOG for _ in range(n + 1)]
    max_edge = [[0] * LOG for _ in range(n + 1)]
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)

    # DFS to build preprocessing tables
    def dfs(u, p, w, d):
        depth[u] = d
        up[u][0] = p
        max_edge[u][0] = w
        visited[u] = True

        for v, e in mst_adj[u]:
            if not visited[v]:
                dfs(v, u, e, d + 1)

    # Root the tree at node 1 (since graph is connected)
    dfs(1, 0, 0, 0)

    # Build binary lifting table
    for j in range(1, LOG):
        for i in range(1, n + 1):
            mid = up[i][j - 1]
            up[i][j] = up[mid][j - 1]
            max_edge[i][j] = max(max_edge[i][j - 1], max_edge[mid][j - 1])

    # Query function: get max edge on path between u and v
    def query_max(u, v):
        if u == v:
            return 0

        # Ensure u is deeper or equal
        if depth[u] < depth[v]:
            u, v = v, u

        res = 0
        diff = depth[u] - depth[v]

        # Lift u to same depth as v
        for j in range(LOG):
            if (diff >> j) & 1:
                res = max(res, max_edge[u][j])
                u = up[u][j]

        if u == v:
            return res

        # Lift both until just below LCA
        for j in range(LOG - 1, -1, -1):
            if up[u][j] != up[v][j]:
                res = max(res, max_edge[u][j], max_edge[v][j])
                u = up[u][j]
                v = up[v][j]

        # One more step to reach LCA
        res = max(res, max_edge[u][0], max_edge[v][0])
        return res

    # Compute results for all non-MST edges
    results = []
    for idx, a, b, e in edges_data:
        if idx not in mst_edge_indices:
            results.append(str(query_max(a, b)))

    return '\n'.join(results)


