def can_encode(S_sub, T_str):
    """Check if S_sub can be transformed to T_str using some valid disjoint pairs."""
    s_to_t = {}
    t_to_s = {}

    for s, t in zip(S_sub, T_str):
        if s == t:
            continue

        # If s already maps to a different t, invalid
        if s in s_to_t and s_to_t[s] != t:
            return False
        # If t already maps to a different s, invalid
        if t in t_to_s and t_to_s[t] != s:
            return False

        s_to_t[s] = t
        t_to_s[t] = s

    # Check that all formed pairs are consistent
    for s, t in s_to_t.items():
        if t_to_s.get(t) != s:
            return False

    return True


