def solution(input_str):
    n, m, k = map(int, input_str.split())

    def log_comb(n, k):
        """Returns log(C(n, k)) or -inf if invalid"""
        if k < 0 or k > n:
            return float('-inf')
        return math.lgamma(n + 1) - math.lgamma(k + 1) - math.lgamma(n - k + 1)

    # Base cases: if no people or only give 10 eurs
    if m == 0:
        return "1.000000000000\n"

    # If we have enough initial 10€ banknotes for all 20€ givers
    if k >= m:
        return "1.000000000000\n"

    # Total paths
    total_log = log_comb(n + m, n)

    # Bad paths using reflection principle: C(n+m, m-k-1)
    bad_log = float('-inf')
    if m - k - 1 >= 0 and m - k - 1 <= n + m:
        bad_log = log_comb(n + m, m - k - 1)

    # Ratio = bad_paths / total_paths
    if total_log == float('-inf'):
        ratio = 0  # Shouldn't happen given constraints
    else:
        # Need to handle numerical underflow
        if bad_log == float('-inf') or (bad_log - total_log) < -700:
            ratio = 0.0
        else:
            ratio = math.exp(bad_log - total_log)

    # Clamp to valid range
    prob = max(0.0, min(1.0, 1.0 - ratio))

    return f"{prob:.10f}\n"


