import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "1\n"
    n = int(lines[0])

    if n <= 1:
        return "1\n"

    adj = [[] for _ in range(n + 1)]
    for i in range(1, min(len(lines), n)):
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    # Tree DP
    # f[i] = max product from subtree when component at node has size i
    def dp(u, p):
        f = [float('-inf')] * (n + 1)
        f[1] = 1  # Component of size 1 with product 1

        for v in adj[u]:
            if v == p:
                continue
            g = dp(v, u)  # Results from child v

            tmp = [float('-inf')] * (n + 1)

            # Try all combinations of current size i (at u) and child size j (at v)
            for i in range(1, n + 1):
                if f[i] <= -1e18:
                    continue
                for j in range(1, n + 1):
                    if g[j] <= -1e18:
                        continue

                    product = f[i] * g[j]

                    # Option 1: Cut edge (u,v) - v's component is complete
                    # Size at u stays i, multiply by child's contribution
                    if tmp[i] < product:
                        tmp[i] = product

                    # Option 2: Keep edge (u,v) - components merge
                    if i + j <= n:
                        if tmp[i+j] < product:
                            tmp[i+j] = product

            f = tmp

        return f

    result = dp(1, -1)

    max_product = 0
    for x in result:
        if x > max_product:
            max_product = x

    return f"{max_product}\n"


