MOD = 1000000007

def solution(input_str):
    lines = input_str.strip().split('\\n')
    n = int(lines[0])

    if n < 3:
        return '0'

    polygon = []
    for i in range(1, n + 1):
        coords = lines[i].split()
        polygon.append((int(coords[0]), int(coords[1])))

    memo = {}

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def is_valid_diagonal(i, j):
        if i == j:
            return False

        p1 = (polygon[i][0], polygon[i][1])
        p2 = (polygon[j][0], polygon[j][1])

        next_i = (i + 1) % n
        sign = cross_product(p1, p2, (polygon[next_i][0], polygon[next_i][1]))
        if abs(sign) < 1e-10:
            return False

        for k in range(n):
            if k == i or k == j:
                continue
            cp = cross_product(p1, p2, (polygon[k][0], polygon[k][1]))
            if sign * cp < 0:
                return False

        return True

    def count_triangulations(start, end):
        if (start, end) in memo:
            return memo[(start, end)]

        if end == start + 1:
            memo[(start, end)] = 1
            return 1

        result = 0
        for k in range(start + 1, end):
            if is_valid_diagonal(start, k):
                result = (result + count_triangulations(start, k) * count_triangulations(k, end)) % MOD

        memo[(start, end)] = result
        return result

    result = 0
    for i in range(n):
        j = (i + n - 1) % n
        result = (result + count_triangulations(i, j)) % MOD

    return str(result)


