    # Sieve of Eratosthenes to find primes up to sqrt(r)
    sqrt_r = int(r ** 0.5) + 1
    is_prime_small = [True] * (sqrt_r + 1)
    is_prime_small[0] = is_prime_small[1] = False

    primes = []
    for i in range(2, sqrt_r + 1):
        if is_prime_small[i]:
            primes.append(i)
            for j in range(i * i, sqrt_r + 1, i):
                is_prime_small[j] = False

    # Create a segment for [l, r]
    segment_size = r - l + 1
    is_prime_segment = [True] * segment_size

    # Mark composites in the range [l, r]
    for p in primes:
        # Find the first multiple of p >= l
        start = ((l + p - 1) // p) * p
        if start < l:
            start += p

        # If the first multiple is before p*p, skip (already sieved)
        if start < p * p:
            start = p * p

        # Mark all multiples of p in the range
        for num in range(start, r + 1, p):
            is_prime_segment[num - l] = False

    # Handle the special case where l itself might be prime
    for p in primes:
        if l == p:
            is_prime_segment[0] = True

    # Count primes that are 2 or congruent to 1 mod 4
    count = 0
    for i in range(segment_size):
        num = l + i
        if is_prime_segment[i]:
            if num == 2 or num % 4 == 1:
                count += 1

    return str(count)

class SegmentTree:
    def __init__(self, n):
        self.n = n
        self.path_sum = [0.0] * (4 * n)
        self.full_prod = [1.0] * (4 * n)
        self.R = [0.0] * (n + 1)

    def build(self, node, start, end):
        if start == end:
            # Leaf
            self.path_sum[node] = self.R[start]
            self.full_prod[node] = self.R[start]
        else:
            mid = (start + end) // 2
            self.build(2 * node, start, mid)
            self.build(2 * node + 1, mid + 1, end)
            self.pull(node, mid, self.R)

    def pull(self, node, mid, R):
        # Merge left child (2*node) and right child (2*node+1)
        # Mid is where the split happens
        self.path_sum[node] = self.path_sum[2*node] + self.full_prod[2*node] * self.path_sum[2*node+1]
        self.full_prod[node] = self.full_prod[2*node] * self.full_prod[2*node+1]

    def update(self, node, start, end, idx, new_R):
        if start == end:
            self.path_sum[node] = new_R
            self.full_prod[node] = new_R
        else:
            mid = (start + end) // 2
            if start <= idx <= mid:
                self.update(2 * node, start, mid, idx, new_R)
            else:
                self.update(2 * node + 1, mid + 1, end, idx, new_R)
            self.pull(node, mid)

    def query(self, node, start, end, l, r):
        if l > end or r < start:
            return 0, 1  # path_sum=0, full_prod=1
        if l <= start and end <= r:
            return self.path_sum[node], self.full_prod[node]
        mid = (start + end) // 2
        ls, lp = self.query(2 * node, start, mid, l, r)
        rs, rp = self.query(2 * node + 1, mid + 1, end, l, r)
        return ls + lp * rs, lp * rp

