    adj = [[] for _ in range(num_input_vertices + 1)]
    for a, b in edges:
        if 1 <= a <= num_input_vertices and 1 <= b <= num_input_vertices:
            adj[a].append(b)
            adj[b].append(a)

    from collections import deque

    # Try each possible vertex as the parent of the removed vertex
    # We need to identify which node could be p where child v was removed

    def build_tree(adj, root):
        parent = {root: None}
        children = {root: []}
        depth = {root: 0}
        visited = {root}
        queue = deque([root])

        while queue:
            v = queue.popleft()
            for u in adj[v]:
                if u not in visited:
                    visited.add(u)
                    children[v].append(u)
                    depth[u] = depth[v] + 1
                    parent[u] = v
                    queue.append(u)

        return parent, children, depth

    valid_parents = []

    # Try vertex 1 as root
    parent, children, depth = build_tree(adj, 1)

    # Check which nodes could be parent of removed vertex
    for p in range(1, num_input_vertices + 1):
        kid_list = children.get(p, [])
        num_children = len(kid_list)
        p_depth = depth.get(p, float('inf'))

        if p_depth == float('inf'):
            continue

        # Expected: after removal, parent has either 3 children (was internal) or 1 child (was leaf)
        if num_children == 3:
            # Check depths of children - should match complete binary tree pattern
            depth_count = {}
            for c in kid_list:
                d = depth.get(c, float('inf'))
                if d != float('inf'):
                    depth_count[d] = depth_count.get(d, 0) + 1

            # Should have one child at p_depth+1 and two children at p_depth+2
            if depth_count.get(p_depth + 1, 0) == 1 and depth_count.get(p_depth + 2, 0) == 2:
                # Verify missing vertex can be added
                valid_parents.append(p)
        elif num_children == 1:
            # One child at correct depth
            child_depths = [depth.get(c, float('inf')) for c in kid_list]
            if any(d == p_depth + 1 for d in child_depths) and all(d == p_depth + 1 for d in child_depths):
                valid_parents.append(p)
        elif num_children == 0:
            # Shouldn't happen for parent of removed vertex, but check anyway
            valid_parents.append(p)

    # Also check if root (vertex 1) should be considered
    root_kid_count = len(children.get(1, []))
    # Root should have 2 children, but could have more after removal (unlikely for root)

    # Deduplicate and sort
    valid_parents = sorted(list(set(valid_parents)))

    if not valid_parents:
        return "0\n"

    # Special handling for n=2 case (already handled above, but for completeness)
    if n == 2:
        return "2\n1 2\n"

