    # Track which clauses each variable appears in
    var_occurrences = defaultdict(list)

    for clause_idx in range(n):
        parts = list(map(int, lines[clause_idx + 1].split()))
        literals = parts[1:]

        for lit_val in literals:
            var = abs(lit_val)
            is_negated = (lit_val < 0)
            var_occurrences[var].append((clause_idx, is_negated))

    appearing_vars = set(var_occurrences.keys())
    free_var_count = m - len(appearing_vars)

    if not appearing_vars:
        return str(pow(2, m, MOD) + '\n')

    # Build adjacency between variables sharing clauses
    var_adj = defaultdict(set)
    for var in appearing_vars:
        var_clauses = set(c for c, _ in var_occurrences[var])
        for other_var in appearing_vars:
            if other_var == var:
                continue
            other_clauses = set(c for c, _ in var_occurrences[other_var])
            if var_clauses & other_clauses:
                var_adj[var].add(other_var)
                var_adj[other_var].add(var)

    assigned = set()
    total = pow(2, free_var_count, MOD) % MOD

    # Process each connected component
    for var in appearing_vars:
        if var not in assigned:
            component = set([var])
            assigned.add(var)
            queue = [var]

            while queue:
                u = queue.pop(0)
                for v in var_adj[u]:
                    if v not in assigned:
                        component.add(v)
                        assigned.add(v)
                        queue.append(v)

            unique_clauses = set()
            for v in component:
                for c, _ in var_occurrences[v]:
                    unique_clauses.add(c)

            num_vars = len(component)
            num_clauses = len(unique_clauses)

            factor = pow(2, max(0, num_vars - num_clauses), MOD)
            total = (total * factor) % MOD

    return str(total + '\n')

