    lines = input_str.strip().split('\n')
    n, h, m = map(int, lines[0].split())

    restrictions = []
    for i in range(m + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) == 4:
            restrictions.append(tuple(map(int, parts)))

    # Build flow network using standard min-cut approach
    S = 0
    T = 1
    num_spot_height = 2 + n * h
    num_violation = num_spot_height + m
    dinic = Dinic(num_violation)

    # Nodes for spot i, height d: node = 2 + (i-1)*h + (d-1)
    # Nodes for violation k: node = 2 + n*h + k

    # Source to spot-height nodes (profit constraint)
    for i in range(1, n + 1):
        for d in range(1, h + 1):
            node = 2 + (i - 1) * h + (d - 1)
            dinic.add_edge(S, node, d * d)

    # Ensure consistent height: selecting height d implies selecting height d-1
    for i in range(1, n + 1):
        for d in range(2, h + 1):
            node_d = 2 + (i - 1) * h + (d - 1)
            node_d_prev = 2 + (i - 1) * h + (d - 2)
            dinic.add_edge(node_d, node_d_prev, float('inf'))

    # For each violation: if any height > x_i is selected in range [l, r], pay c_i
    for k in range(m):
        l, r, x, c = restrictions[k]
        violation_node = num_spot_height + k
        dinic.add_edge(S, violation_node, c)  # Option to pay violation cost

        # Add infinite edges from heights above x to violation node
        for i in range(l, r + 1):
            for d in range(x + 1, h + 1):
                node = 2 + (i - 1) * h + (d - 1)
                dinic.add_edge(node, violation_node, float('inf'))

    # Spot height h goes to sink (enforce max height constraint)
    for i in range(1, n + 1):
        node = 2 + (i - 1) * h + (h - 1)
        dinic.add_edge(node, T, float('inf'))

    max_flow = dinic.max_flow(S, T)

    # Compute max profit: sum(h_i^2) - max_fines
    # Min cut gives us the minimum "penalty + opportunity loss"
    total_gain = 0
    for i in range(1, n + 1):
        for d in range(1, h + 1):
            if d > 0:
                node = 2 + (i - 1) * h + (d - 1)
                gain = node  # Store d^2 profit
                total_gain += gain

    # The max_flow helps us determine which heights to cut for restrictions
    # Since the structure allows direct comparison between gains and costs,
    # we compute max profit using the min-cut formulation

    profit = total_gain - max_flow

    return str(profit)


