    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Build edge constraints
    # If both x and a-x exist, they must be in the same set
    # If both x and b-x exist, they must be in the same set

    # Use Union-Find to group numbers that must be together
    parent = list(range(n))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    for i in range(n):
        x = p[i]
        if (a - x) in p and x != a - x:
            # Find index of a-x
            j = p.index(a - x)
            union(i, j)
        if (b - x) in p and x != b - x:
            j = p.index(b - x)
            union(i, j)

    # Process connected components
    result = [0] * n
    possible = True

    for root in range(n):
        if find(root) == root:
            # Try to assign all numbers in this component to A (0)
            component = []
            for i in range(n):
                if find(i) == root:
                    component.append(i)

            # Check if all can be in A
            valid_for_A = True
            for i in component:
                x = p[i]
                if (a - x) in p:
                    j = p.index(a - x)
                    if result[j] != 0:  # If a-x already assigned to B
                        valid_for_A = False
                        break
                if (b - x) in p:
                    j = p.index(b - x)
                    if result[j] != 0:  # If b-x already assigned to B
                        valid_for_A = False
                        break

            if valid_for_A:
                for i in component:
                    result[i] = 0
            else:
                # Try assigning to B (1)
                valid_for_B = True
                for i in component:
                    x = p[i]
                    if (b - x) in p:
                        j = p.index(b - x)
                        if result[j] != 1:  # If b-x already assigned to A
                            valid_for_B = False
                            break
                    if not valid_for_B:
                        break

                if valid_for_B:
                    for i in component:
                        result[i] = 1
                else:
                    # No valid assignment possible
                    possible = False
                    break

    if possible:
        return 'YES\n' + ' '.join(map(str, result)) + '\n'
    else:
        return 'NO\n'

