            while self.pos < self.length and (self.expr[self.pos].isdigit() or self.expr[self.pos] == '0'):
                num_str += self.expr[self.pos]
                self.pos += 1
            return num_str, len(num_str)

        def generate_range_str(self, start_str, end_str):
